        /**
         * stav akce ve statusbaru                windowContent.on("bar_savepoadavek", function (retVal) {
         * @type {GObservableObject<MenuParams>}
         */
        private statusBarStavPozadavku: GObservableObject<MenuParams>;

        onContentReady() {

            var that = this;
            var $tab = $(this.contentDiv);

            var fields = this.findFields(); // všechny políčka

            var newDtoIntervalFin: GIntervalDto<number> = { start: 0, end: 0 };
            newDtoIntervalFin.start = this.modelbar.fin_od!;
            newDtoIntervalFin.end = this.modelbar.fin_do!;

            var newDtoIntervalReal: GIntervalDto<number> = { start: 0, end: 0 };
            newDtoIntervalReal.start = this.modelbar.real_od!;
            newDtoIntervalReal.end = this.modelbar.real_do!;

            var newDtoIntervalObdobi = { interval_fin: newDtoIntervalFin, interval_real: newDtoIntervalReal };

            fields.gfield("model", "apply", this.modelbar, { initialValues: true }); // nastaví hodnoty jako initValue, pak se dá zeptat na hasChanged (porovná initialValue vs value, použije se např. v closing).
            this.findForms("HlavniForm_Obdobi").findFields().gfield("model", "apply", newDtoIntervalObdobi, { initialValues: true });

            this.filter_akce.rok = this.modelbar.rok_srv;
            this.filter_akce.cislo = this.modelbar.cislo;

            if ((that.globals.Param_Rezim_Vlastnik === true) && (this.modelbar.Permissions?.JsemVlastnik.value === false)) {
                that.editable = false
            }

            this.form_disabled = (this.editable === false);
            this.form_novaakce = (this.novaakce === true);

            if (this.form_novaakce == true) {
                this.title = "Nový požadavek";
            }
            else {
                this.title = "Požadavek " + that.modelbar.ixp;
            }

            if (this.form_disabled) {
                fields.findFields().gfield("option", "disabled", true) // vždy enabled
            }

        }

