            var that = this;
            var t: GKpiItemOptions;

            this.statusBarStavPozadavku = new GObservableObject<MenuParams>({ visible: true, id: "statusstavpozadavku", tooltip: "Stav požadavku", caption: that.modelbar.aktivita_s!, type: "static", customClass: (that.modelbar.aktivita == Interface.AktivitaAkceEnum.Aktivni) ? "g-state-success g-state-text" : "g-state-error g-state-text" });

