                            var vybraneRadky: Gordic.Bar.Interface.GSrvsixpDto[] = [];
                            var v_radek: Gordic.Bar.Interface.GSrvsixpDto = {};
                            v_radek.rok_srv = that.modelbar.rok_srv;
                            v_radek.ico = that.modelbar.ico;
                            v_radek.ixp = that.modelbar.ixp;
                            v_radek.aktivita = that.modelbar.aktivita;

