        // metoda vyvolání uložení pozadavku
        uloz_pozadavek() {
            var that = this;
            var $cDiv = $(this.contentDiv);
            //this.contentDiv.showFlash({ label: 'Ukladam akci ' + cislo });
            if ($cDiv.findForms().gform("isValid", true)) {
                //var dto = {};
                $cDiv.findForms((["form_zaklad", Gordic.Eko.HeaderForm.Name]).join(",")).findFields().gfield("model", "collect", this.modelbar);
                $cDiv.findFields().gfield("confirm");

                // jeste prepisu hodmnty z pomocnych DTO (fin a real)
                var newDtoIntervalFin: GIntervalDto<number> = { start: 0, end: 0 };
                newDtoIntervalFin.start = this.modelbar.fin_od!;
                newDtoIntervalFin.end = this.modelbar.fin_do!;

                var newDtoIntervalReal: GIntervalDto<number> = { start: 0, end: 0 };
                newDtoIntervalReal.start = this.modelbar.real_od!;
                newDtoIntervalReal.end = this.modelbar.real_do!;

                var newDtoIntervalObdobi = { interval_fin: newDtoIntervalFin, interval_real: newDtoIntervalReal };

                $cDiv.findForms("HlavniForm_Obdobi").findFields().gfield("model", "collect", newDtoIntervalObdobi);

                this.modelbar.fin_od = newDtoIntervalObdobi.interval_fin.start;
                this.modelbar.fin_do = newDtoIntervalObdobi.interval_fin.end;
                this.modelbar.real_od = newDtoIntervalObdobi.interval_real.start;
                this.modelbar.real_do = newDtoIntervalObdobi.interval_real.end;

                //that.actions.actAdaAkceDokladUlozAkci!.setPending(0);

                let prom_vysledek =
                    this.call("Save", { dto: this.modelbar })
                            .done(function (out_data) {
                                that.trigger("bar_savepoadavek", [{ data: { ixp: out_data.ixp } }]);

                                that.form_novaakce = false;
                                that.title = "Požadavek " + that.modelbar.ixp; //aby se dalo přistoupit z breadcrumbs, je nastaveno zde místo v C#

                                //JI XXX
                                //that.tryClose();

                                that.load({ ixp: out_data.ixp });

                            });
                that.actions.actBarUlozit!.setPending(prom_vysledek);

                return prom_vysledek;
            }
        }

